/* The float formatter against the reference's own output for thousands of values.
 *
 * The corpus is generated by tools/make_float_corpus.py from orjson, which is what
 * the Python implementation's json lane uses, so a mismatch here is a real
 * difference in the wire bytes.
 */
#include "aln.h"

#include <stdint.h>
#include <stdio.h>
#include <string.h>

int main(void) {
    FILE *file = fopen(ALN_FIXTURE_DIR "/float_corpus.txt", "r");
    if (file == nullptr) {
        printf("FAIL: cannot open the corpus\n");
        return 1;
    }
    char bits_text[32];
    char expected[64];
    int checked = 0;
    int failed = 0;
    while (fscanf(file, "%31s %63s", bits_text, expected) == 2) {
        uint64_t bits = 0;
        for (int index = 0; index < 16; ++index) {
            const char character = bits_text[index];
            const uint64_t nibble =
                (character <= '9') ? (uint64_t)(character - '0') : (uint64_t)(character - 'a' + 10);
            bits = (bits << 4) | nibble;
        }
        double value;
        memcpy(&value, &bits, sizeof value);
        char actual[64];
        const size_t length = aln_format_double(actual, sizeof actual, value);
        ++checked;
        if (length == 0 || strcmp(actual, expected) != 0) {
            ++failed;
            if (failed <= 10) {
                printf("MISMATCH %s: ours %s, reference %s\n", bits_text, actual, expected);
            }
        }
    }
    fclose(file);
    printf("%s: %d values, %d mismatches\n", failed == 0 ? "ok" : "FAILED", checked, failed);
    return failed == 0 ? 0 : 1;
}
